import{_ as n,a as t,b as i,c as r,d as s,e as d,f as a}from"./chunks/linebox-math-dialog.C07gskZO.js";import{_ as g,o as u,c as o,a3 as h}from"./chunks/framework.BlfGB29P.js";const w=JSON.parse('{"title":"SVG LineBox Math","description":"","frontmatter":{"title":"SVG LineBox Math"},"headers":[],"relativePath":"projects/grafik-visual-studio/svg-linebox-math.md","filePath":"projects/grafik-visual-studio/svg-linebox-math.md","lastUpdated":1793023597000}'),l={name:"projects/grafik-visual-studio/svg-linebox-math.md"};function c(b,e,m,p,f,k){return u(),o("div",null,[...e[0]||(e[0]=[h('<h1 id="svg-linebox-math" tabindex="-1">SVG LineBox Math <a class="header-anchor" href="#svg-linebox-math" aria-label="Permalink to &quot;SVG LineBox Math&quot;">​</a></h1><h2 id="praxisbeispiel-zwei-positive-leistungswerte-zusammenfuhren" tabindex="-1">Praxisbeispiel: Zwei positive Leistungswerte zusammenführen <a class="header-anchor" href="#praxisbeispiel-zwei-positive-leistungswerte-zusammenfuhren" aria-label="Permalink to &quot;Praxisbeispiel: Zwei positive Leistungswerte zusammenführen&quot;">​</a></h2><p>Ein Wechselrichter kann Lade- und Entladeleistung als <strong>zwei getrennte, jeweils positive Werte</strong> bereitstellen. Für eine gemeinsame Leistungsanzeige muss daraus ein Wert entstehen, dessen Vorzeichen die Flussrichtung unterscheidet. <strong>SVG LineBox Math</strong> berechnet diese Differenz direkt im Browser des Displays. Zusätzliche Home-Assistant-Template-Sensoren oder Automationen sind dafür nicht erforderlich: Home Assistant liefert die Sensorwerte, der Display-Computer übernimmt die Rechnung. Die bestehende Verbindung und Werteübertragung verursachen weiterhin Last.</p><h3 id="editor-werte-erfassen-und-berechnen" tabindex="-1">Editor: Werte erfassen und berechnen <a class="header-anchor" href="#editor-werte-erfassen-und-berechnen" aria-label="Permalink to &quot;Editor: Werte erfassen und berechnen&quot;">​</a></h3><p><img src="'+n+'" alt="Editor mit farbigen Number-Widgets, Wert-Verbindungen und MathBox neben der Batterieanzeige"></p><p><em>Die farbigen Hilfswidgets machen die Verarbeitung im Editor nachvollziehbar. Rot und Blau unterscheiden die beiden positiven Eingangswerte; die graue MathBox zeigt das berechnete Ergebnis. Die Anschlussbuchstaben und Griffe sind Editor-Hilfen.</em></p><table tabindex="0"><thead><tr><th>Widget</th><th>Aufgabe im Beispiel</th></tr></thead><tbody><tr><td>Zwei <strong>Number-Widgets</strong>, rot und blau</td><td>Je einen Sensorwert für Laden beziehungsweise Entladen einlesen und über den aktivierten Datenfluss-Ausgangspunkt weitergeben. Die Farben dienen der Unterscheidung, sie bestimmen kein Vorzeichen.</td></tr><tr><td><strong>Wert-Verbindungen</strong></td><td>Die Number-Ausgänge mit den Math-Eingängen <strong>O</strong> und <strong>M</strong> verbinden und das berechnete Ergebnis vom Ausgang <strong>A</strong> an die Leistungsanzeige weitergeben. Diese Leitungen sind in der Runtime unsichtbar.</td></tr><tr><td><strong>SVG LineBox Math</strong>, grau</td><td>Beide positiven Eingänge voneinander abziehen und die resultierende Leistung samt Vorzeichen über <strong>A</strong> ausgeben.</td></tr><tr><td><strong>Industrial-Batterieanzeige</strong></td><td>Die berechnete Leistung darstellen. Temperatur und Ladezustand bleiben separate Messwerte; sie sind nicht Bestandteil dieser Differenzrechnung.</td></tr><tr><td><strong>SVG-Lines</strong></td><td>Den dargestellten Energiefluss zwischen Solarmodulen und Batterie sichtbar machen. Sie können animiert werden; ihre Richtung muss zur jeweiligen Start-/Zielzuordnung und Vorzeichenkonvention passen.</td></tr><tr><td><strong>Number-Anzeigen an den Solarleitungen</strong></td><td>Die jeweilige Solarleistung anzeigen; diese Werte gehören nicht zu den beiden Eingängen der Batterie-Differenzrechnung.</td></tr><tr><td><strong>Industrial-Solarmodule</strong></td><td>Die beiden PV-Quellen grafisch darstellen.</td></tr></tbody></table><p>Im Editorbild sind <strong>O = 1249</strong> und <strong>M = 0</strong> angeschlossen; die MathBox zeigt <strong>1249</strong>. Für diese Zuordnung lautet die Differenz <strong><code>O - M</code></strong>. Richte <strong>O</strong> und <strong>M</strong> als Eingänge und <strong>A</strong> als Ausgang ein. Aktiviere Rechnung 1, wähle <strong>Eigene Formel</strong>, trage <code>O - M</code> und unter <strong>Ausgänge</strong> <code>A</code> ein. <strong>Ergebnis intern an Eingang übergeben</strong> bleibt ausgeschaltet. Aktiviere bei beiden Number-Widgets den Ausgangspunkt und verbinde jeweils genau diesen Punkt.</p><p>Die Bedeutung des Vorzeichens legst du durch die Sensorzuordnung fest. Wenn <strong>O die Ladeleistung</strong> und <strong>M die Entladeleistung</strong> liefert, gilt:</p><table tabindex="0"><thead><tr><th>Ladeleistung O</th><th>Entladeleistung M</th><th>Ergebnis O − M</th><th>Bedeutung</th></tr></thead><tbody><tr><td>1249 W</td><td>0 W</td><td>+1249 W</td><td>Laden</td></tr><tr><td>0 W</td><td>420 W</td><td>−420 W</td><td>Entladen</td></tr><tr><td>0 W</td><td>0 W</td><td>0 W</td><td>Kein Nettofluss</td></tr></tbody></table><p>Sind die Sensoren umgekehrt angeschlossen, kehrt sich die Bedeutung des Vorzeichens um. Für die entgegengesetzte Konvention verwende <code>M - O</code>. Bei gleichzeitig positiven Werten zeigt die Differenz den <strong>Nettofluss</strong>, nicht beide Einzelleistungen. Eine echte <strong>0</strong> ist ein gültiger Eingangswert; ein fehlender oder ungültiger Sensorwert wird nicht automatisch durch null ersetzt.</p><h3 id="runtime-anzeige-ohne-hilfswidgets" tabindex="-1">Runtime: Anzeige ohne Hilfswidgets <a class="header-anchor" href="#runtime-anzeige-ohne-hilfswidgets" aria-label="Permalink to &quot;Runtime: Anzeige ohne Hilfswidgets&quot;">​</a></h3><p><img src="'+t+'" alt="Runtime mit Solarleitungen und Batterieanzeige; die farbigen Hilfswidgets und MathBox sind verborgen"></p><p><em>Die Runtime zeigt die fertige Visualisierung. Die Batterie-Leistung erscheint blau, die Temperatur magenta und der Ladezustand grün. Der Richtungspfeil unterstützt die Zuordnung des Energieflusses. Die Aufnahmen stammen aus unterschiedlichen Momenten; die Messwerte müssen daher nicht übereinstimmen.</em></p><p>Ab <strong>Studio 0.1.287</strong> setzt du bei den beiden Hilfs-Number-Widgets und der MathBox oben im Reiter <strong>WIDGET</strong> die Checkbox <strong>In Runtime verstecken</strong> und speicherst das Projekt. Sie bleiben im Editor sichtbar und bearbeitbar, erscheinen aber nicht auf dem Display. <strong>Ihre Werteübergaben und Rechnungen laufen weiter.</strong> Die sichtbaren Leistungsanzeigen, Batterieelemente und SVG-Lines bleiben eingeblendet.</p><p>Die Berechnung läuft pro geöffnetem Display im jeweiligen Browser. Sie erzeugt durch die lokale Wertübergabe keine zusätzliche HA-Entität und schreibt das Ergebnis nicht automatisch nach Home Assistant zurück. Wenn das Display beziehungsweise sein Browser geschlossen ist, läuft dort auch diese Berechnung nicht weiter.</p><h2 id="alternative-zuordnung-batterie-→-wechselrichter" tabindex="-1">Alternative Zuordnung: Batterie → Wechselrichter <a class="header-anchor" href="#alternative-zuordnung-batterie-→-wechselrichter" aria-label="Permalink to &quot;Alternative Zuordnung: Batterie → Wechselrichter&quot;">​</a></h2><p>Ein <strong>Number</strong>-Widget kann einen Entitäts- oder Vorschauwert an Math liefern. Aktiviere seinen <strong>Ausgangspunkt</strong> unter <strong>Datenfluss</strong> und verbinde genau diesen Punkt mit einem aktiven Math-Eingang. Für unsichtbare Leitungen nutze Wert-Verbindungen oder ab <strong>0.1.285</strong> SVG-Lines mit explizitem <strong>Z-Index −100 oder kleiner</strong>. Die Darstellung verschwindet in der Runtime, die Werte bleiben aktiv.</p><p>Wenn <strong>P zur Batterie</strong> und <strong>O aus der Batterie</strong> fließt, gilt für eine Linie Batterie → Wechselrichter:</p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Wert</th></tr></thead><tbody><tr><td>O</td><td>Eingang; <code>sensor.hyper_2000_eg_1_output_pack_power</code></td></tr><tr><td>P</td><td>Eingang; <code>sensor.hyper_2000_eg_1_pack_input_power</code></td></tr><tr><td>A</td><td>Ausgang</td></tr><tr><td>Rechnung 1</td><td>Aktivieren; Eigene Formel</td></tr><tr><td>Formel</td><td><code>O - P</code></td></tr><tr><td>Ausgänge</td><td><code>A</code></td></tr><tr><td>Interne Übergabe</td><td>Aus</td></tr></tbody></table><p>Beide Sensoren dürfen positive Zahlen liefern: O = 0, P = 1252 ergibt <strong>−1252 W</strong> (Laden); O = 150, P = 0 ergibt <strong>+150 W</strong> (Entladen). Bei gleichzeitig aktiven Werten ergibt sich der Nettofluss. Eine echte <strong>0 ist gültig</strong>. „Eingang O: Wert fehlt …“ bedeutet, dass kein gültiger Wert über die Verbindung ankommt: Ausgang aktivieren, passenden Ausgangspunkt prüfen und das Linienziel dem Eingang O zuordnen. Fehlende Werte werden nicht als Null behandelt.</p><p>Ab <strong>0.1.141</strong> blendet <strong>In Runtime ausblenden</strong> unter Berechnung nur die Darstellung aus; alle Rechnungen und Wertübergaben bleiben aktiv. Die Variante <strong>Wert-Berechnung</strong> in <a href="./datenfluss">HA Grafik – Datenfluss</a> verwendet dieselbe Logik und startet mit dieser Option eingeschaltet. Wert-Konverter und unsichtbare Wert-Verbindungen können vorgeschaltet werden.</p><p>Ab Studio <strong>0.1.138</strong> enthält der vergrößerte Dialog <strong>vier getrennte Rechnungen</strong>. Jede hat eine eigene Aktivierung, Formel beziehungsweise Durchschnittsberechnung, Ausgangsliste und Ergebnisvorschau. Rechnung 1 übernimmt bei älteren Projekten die bisherige Berechnung und ihre Ausgänge; Rechnungen 2–4 sowie alle internen Eingangsübergaben sind zunächst aus.</p><h2 id="große-icon-und-farben" tabindex="-1">Größe, Icon und Farben <a class="header-anchor" href="#große-icon-und-farben" aria-label="Permalink to &quot;Größe, Icon und Farben&quot;">​</a></h2><p>Ab <strong>0.1.140</strong> stehen im Reiter <strong>WIDGET</strong> dieselben fünf CSS-Bereiche wie bei den Basis-Widgets bereit: <strong>CSS Allgemein</strong>, <strong>CSS Font &amp; Text</strong>, <strong>CSS Hintergrund</strong>, <strong>CSS Ränder</strong> und <strong>CSS Schatten und Abstand</strong>. Damit lassen sich Position, Anzeige, Transparenz, Schrift, Textausrichtung, Hintergrundbild, Rahmen, <strong>Eckenradius</strong>, Schatten und Innen-/Außenabstände einstellen. Schriftgröße, Textausrichtung, Eckenradius und Innenabstand werden auch für LineBox Math übernommen. Die Dockpunkte behalten beim Abrunden ihre bisherigen geometrischen Positionen; größere Radien können die sichtbare Rahmenkante von den Eckpunkten entfernen. Der zusätzliche CSS-Stil hat weiterhin Vorrang vor den entsprechenden Feldern. Der Reiter <strong>CSS</strong> enthält dagegen das globale Projekt-CSS.</p><p>Ab <strong>0.1.139</strong> sind Breite und Höhe unabhängig zwischen <strong>32 und 2000 px</strong> einstellbar: im Berechnungsdialog oder über die Größenanfasser im Editor. Rechteckige Formen sind möglich. Die 16 Dockpunkte behalten ihre relative Position; Leitungen treten weiterhin rechtwinklig ein. Bei kleinen Widgets werden die Editor-Markierungen kleiner, damit sie nicht überlappen. Für bequemes Zuordnen der Buchstaben empfiehlt sich eine größere Editoransicht; in der Runtime sind die Markierungen ausgeblendet.</p><p>Unter <strong>Darstellung</strong> wählst du ein optionales Icon, seine Größe (8–512 px) und Farbe sowie Hintergrund-, Rahmen- und Ergebnistextfarbe. Icons werden an den verfügbaren Platz angepasst. Die Färbung setzt ein färbbares Icon voraus; mehrfarbige Rasterbilder behalten ihre Bildfarben. <strong>Ergebnis anzeigen</strong> lässt sich ausschalten, ohne Berechnung oder Weitergabe zu stoppen. Für 32 × 32 px sind ein Icon und ausgeblendeter Ergebnistext sinnvoll.</p><p><strong>Zusätzlicher CSS-Stil</strong> erlaubt unterstützte Inline-Deklarationen, zum Beispiel <code>border-radius: 4px; opacity: 0.8;</code>. Er wird nach den Farbfeldern angewendet und kann diese überschreiben. URLs und ausführbare Ausdrücke sind darin nicht zugelassen.</p><p><img src="'+i+'" alt="Kleine LineBox Math mit Taschenrechner-Icon"></p><p><em>Kleines Editorbeispiel mit Icon und ausgeblendetem Ergebnistext.</em></p><p><a href="/images/grafik-visual-studio/math-size-icon.png">Bild in voller Größe öffnen</a></p><p><img src="'+r+'" alt="Per CSS abgerundete LineBox Math"></p><p><em>Unter CSS Ränder ist ein Eckenradius von 24 px eingestellt. Die sichtbaren Editor-Anschlüsse behalten ihre Position.</em></p><p><a href="/images/grafik-visual-studio/math-css.png">Bild in voller Größe öffnen</a></p><h2 id="darstellung-in-der-runtime" tabindex="-1">Darstellung in der Runtime <a class="header-anchor" href="#darstellung-in-der-runtime" aria-label="Permalink to &quot;Darstellung in der Runtime&quot;">​</a></h2><p><img src="'+s+'" alt="LineBox-Math-Quadrat mit Ergebnis 90 und rechtwinkligen Verbindungen"></p><p><em>Runtime-Testszene: Quadrat und Ergebnis bleiben sichtbar, die Leitungen treten rechtwinklig ein und aus. Anschlussbuchstaben und Auswahlgriffe des Editors sind ausgeblendet. Das Ergebnis folgt der eingestellten Rechnung und der Summierung je belegtem Eingangsanschluss.</em></p><p><a href="/images/grafik-visual-studio/math-runtime.png">Bild in voller Größe öffnen</a></p><h2 id="vier-rechnungen-und-ausgangszuordnung" tabindex="-1">Vier Rechnungen und Ausgangszuordnung <a class="header-anchor" href="#vier-rechnungen-und-ausgangszuordnung" aria-label="Permalink to &quot;Vier Rechnungen und Ausgangszuordnung&quot;">​</a></h2><p><img src="'+d+'" alt="Erweiterter SVG-LineBox-Math-Dialog mit separaten Rechnungen und interner Übergabe an Eingang C"></p><p>Der aktuelle Screenshot zeigt die getrennten Rechnungen und die aktivierte interne Übergabe an C. So kann Rechnung 2 das Ergebnis von Rechnung 1 direkt weiterverarbeiten.</p><h2 id="berechnung-auf-dem-display-computer" tabindex="-1">Berechnung auf dem Display-Computer <a class="header-anchor" href="#berechnung-auf-dem-display-computer" aria-label="Permalink to &quot;Berechnung auf dem Display-Computer&quot;">​</a></h2><p>Die Berechnungen laufen im Browser des jeweiligen Display-Computers. Home Assistant liefert die Entitätswerte; SVG LineBox Math berechnet daraus die Ergebnisse und gibt sie innerhalb der Visualisierung an andere Widgets weiter. Auch verkettete Rechnungen mit mehreren Ein- und Ausgängen benötigen dafür weder zusätzliche HA-Entitäten noch HA-Automationen.</p><p>Damit übernimmt der Display-Computer die Rechenarbeit und die Darstellung. Jedes geöffnete Display berechnet seine eigene Visualisierung. Home Assistant bleibt für die Verbindung und den Austausch der Entitätswerte zuständig; diese Kommunikation verursacht weiterhin Last. Die lokalen Math-Ergebnisse werden durch die interne Dockpunktübergabe nicht automatisch in Home Assistant gespeichert.</p><p>Berechnungen stehen nur zur Verfügung, solange die Visualisierung geöffnet ist und ihr Browser ausgeführt wird. Für Abläufe, die auch bei ausgeschaltetem Display zuverlässig weiterlaufen sollen, bleibt eine serverseitige Berechnung oder HA-Automation erforderlich.</p><h2 id="ausgange-konfigurieren" tabindex="-1">Ausgänge konfigurieren <a class="header-anchor" href="#ausgange-konfigurieren" aria-label="Permalink to &quot;Ausgänge konfigurieren&quot;">​</a></h2><p>Stelle zuerst oben die Rollen der Anschlüsse ein. Trage dann je aktivierter Rechnung unter <strong>Ausgänge (z. B. E,F;H)</strong> die gewünschten Buchstaben ein. Komma, Semikolon und Leerzeichen sind als Trennzeichen erlaubt; Kleinbuchstaben werden ebenfalls erkannt. <code>E,F;H</code> ordnet dasselbe Ergebnis den drei Ausgängen E, F und H zu. Jeder dieser Punkte muss ein aktiver <strong>Ausgang</strong> sein. Ist ein Buchstabe als Eingang eingerichtet, erscheint ein Hinweis; eine widersprüchliche Zuordnung lässt sich nicht übernehmen. Ein Ausgang darf nur einer Rechnung zugeordnet sein. Ein Ausgang ohne Zuordnung liefert keinen Wert.</p><h2 id="ergebnisse-intern-weiterverarbeiten" tabindex="-1">Ergebnisse intern weiterverarbeiten <a class="header-anchor" href="#ergebnisse-intern-weiterverarbeiten" aria-label="Permalink to &quot;Ergebnisse intern weiterverarbeiten&quot;">​</a></h2><p>Jede Rechnung hat die zunächst ausgeschaltete Option <strong>Ergebnis intern an Eingang übergeben</strong>. Erst nach dem Einschalten kannst du unter <strong>Interner Eingang</strong> einen einzelnen aktiven Eingangs-Buchstaben wählen. Andere Rechnungen dürfen diesen Buchstaben anschließend in ihren Formeln verwenden. Die interne Übergabe ersetzt an diesem Punkt die externen Leitungswerte; nach dem Ausschalten gelten wieder die angeschlossenen Leitungen. Pro Eingang ist nur ein internes Ergebnis erlaubt. Die Reihenfolge der Rechnungsnummern spielt für die Auflösung von Abhängigkeiten keine Rolle.</p><p>Beispiel mit A = 150 und B = 30:</p><table tabindex="0"><thead><tr><th>Rechnung</th><th>Formel</th><th>Ausgänge</th><th>Interne Übergabe</th><th>Ergebnis</th></tr></thead><tbody><tr><td>1</td><td><code>A + B</code></td><td><code>E,F;H</code></td><td>eingeschaltet → Eingang C</td><td>180</td></tr><tr><td>2</td><td><code>C * 2</code></td><td><code>G</code></td><td>aus</td><td>360</td></tr><tr><td>3</td><td><code>A - B</code></td><td><code>I</code></td><td>aus</td><td>120</td></tr><tr><td>4</td><td>deaktiviert</td><td>—</td><td>aus</td><td>—</td></tr></tbody></table><p>Eine Rechnung darf ihr Ergebnis nicht an einen Eingang zurückführen, von dem sie selbst abhängt. Direkte und indirekte Rückkopplungen sowie doppelte Zuordnungen werden gemeldet und vor dem Übernehmen zurückgewiesen. Bei <strong>Durchschnitt aller belegten Eingänge</strong> zählen auch aktiv zugewiesene interne Eingänge mit; eine Übergabe dieser Durchschnittsrechnung an ihren eigenen Eingangsbereich wäre daher eine Rückkopplung.</p><p>Ein Rechenfehler wie Division durch null stoppt die betreffende Rechnung und ihre abhängigen Rechnungen. Unabhängige Rechnungen arbeiten weiter. Fehlende Werte sind nur dann relevant, wenn die Rechnung diesen Eingang verwendet; eine Durchschnittsrechnung benötigt gültige Werte an allen belegten Eingängen. Der Dialog zeigt Hinweise pro Rechnung. Bei kleinen Bildschirmen wird der Inhalt scrollbar und die Rechnungsbereiche stehen untereinander.</p><h2 id="grundlagen-und-beispiel-einer-einzelrechnung" tabindex="-1">Grundlagen und Beispiel einer Einzelrechnung <a class="header-anchor" href="#grundlagen-und-beispiel-einer-einzelrechnung" aria-label="Permalink to &quot;Grundlagen und Beispiel einer Einzelrechnung&quot;">​</a></h2><p>Das folgende Bild zeigt den ursprünglichen Dialog aus Studio 0.1.137. Die Berechnung funktioniert weiterhin als Rechnung 1 im erweiterten Dialog.</p><p><img src="'+a+'" alt="SVG LineBox Math: Berechnungsdialog mit Anschlüssen A–P, Eingangswerten und Durchschnitt 90"></p><p>Das Bild zeigt den Berechnungsdialog mit <strong>Durchschnitt aller belegten Eingänge</strong>. Eingang <strong>A</strong> enthält bereits die Summe seiner beiden Leitungen (100 + 50 = <strong>150</strong>), Eingang <strong>B</strong> liefert <strong>30</strong>. Daher lautet das Ergebnis <strong>90</strong>. <strong>G</strong> ist als Ausgang eingerichtet und gibt dieses Ergebnis weiter. Die grünen Buchstaben A, B und G kennzeichnen angeschlossene Punkte; die orangefarbenen Buchstaben sind ohne Leitung. Ein unverbundener Eingang mit <code>—</code> zählt beim Durchschnitt nicht mit. Bei dieser Berechnungsart ist das Formelfeld deaktiviert, seine bisherige Formel bleibt jedoch erhalten.</p><p>Ab Studio 0.1.137 steht <strong>SVG LineBox Math</strong> ebenfalls unter <strong>HA Grafik – Spezial</strong>. Es bleibt als Quadrat im Editor und in der Runtime sichtbar. Seine 16 Anschlüsse heißen im Uhrzeigersinn A–P, beginnend links oben: A–E oben, E–I rechts, I–M unten und M–A links. Jede Seite besitzt drei zusätzliche Punkte zwischen ihren Ecken. Im Editor sind angeschlossene Punkte grün und freie Punkte orange, mit kontrastreichen Buchstaben; in der Runtime verschwinden die Markierungen. Leitungen treten rechtwinklig ein. A/E werden von oben, I/M von unten angefahren; die seitlichen Punkte über ihre jeweilige Seitenkante.</p><p>Wähle das Widget und öffne <strong>Berechnung bearbeiten</strong>. Dort stellst du Breite und Höhe (32–2000 px), die Rollen <strong>Aus</strong>, <strong>Eingang</strong> und <strong>Ausgang</strong> für jeden Buchstaben sowie die Berechnung ein. Neue Andockpunkte sind zunächst ausgeschaltet; eine Eingangs- oder Ausgangsrolle im Dialog aktiviert den jeweiligen Punkt. Alle Punkte lassen sich auch im Bereich <strong>Andockpunkte</strong> gemeinsam einschalten.</p><p><strong>Eigene Formel</strong> unterstützt <code>+</code>, <code>-</code>, <code>*</code>, <code>/</code>, Klammern, Zahlen mit Dezimalpunkt und die Buchstaben A–P. Multiplikation und Division gehen vor Addition und Subtraktion. Beispiel: <code>(A + B) / C</code>. Mehrere Leitungen an einem Eingang werden zunächst mit Vorzeichen summiert: A mit 100 und 50 ergibt 150; B mit 30 ergibt bei <code>A - B</code> den Wert 120. <strong>Durchschnitt aller belegten Eingänge</strong> zählt jeden belegten Eingangsanschluss einmal, hier also <code>(150 + 30) / 2 = 90</code>; unbelegte Punkte bleiben unberücksichtigt.</p><p>Die Vorschau zeigt Eingangswerte und Ergebnis. Ausgänge geben das Ergebnis intern an SVG-Lines, weitere LineBoxes und Widgets mit numerischer Dockpunktübernahme weiter. Eine zusätzliche HA-Entität ist nicht nötig. Fehlende oder ungültige angeschlossene Werte, nicht belegte Formel-Eingänge, Division durch null und Rückkopplungen stoppen die Ausgabe. Das Widget zeigt dann <code>—</code> mit Fehlerhinweis; Formeln werden ohne JavaScript-Ausführung ausgewertet. Der Dialog übernimmt Änderungen erst mit <strong>Anwenden</strong> und unterstützt Rückgängig.</p>',61)])])}const A=g(l,[["render",c]]);export{w as __pageData,A as default};
